import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
  FieldDefinition,
} from '../ir/types';

export interface MarkdownGeneratorOptions {
  title?: string;
  includeToc?: boolean;
}

/**
 * Generates clean GitHub-Flavored Markdown data dictionaries from SchemaDocument AST.
 */
export function generateMarkdown(
  doc: SchemaDocument,
  options: MarkdownGeneratorOptions = { includeToc: true }
): string {
  const lines: string[] = [
    `# ${options.title || doc.title || 'Data Schema Specification'}`,
    '',
    doc.description ? `${doc.description}\n` : '',
    '> Auto-generated by TypeBridge. Do not edit directly.',
    '',
  ];

  const structs = doc.definitions.filter(
    (d): d is Extract<TypeDefinition, { kind: 'struct' }> => d.kind === 'struct'
  );
  const enums = doc.definitions.filter(
    (d): d is Extract<TypeDefinition, { kind: 'enum' }> => d.kind === 'enum'
  );

  if (options.includeToc && (structs.length > 0 || enums.length > 0)) {
    lines.push('## Table of Contents', '');
    if (structs.length > 0) {
      lines.push('### Models');
      for (const s of structs) {
        lines.push(`- [${s.name}](#${s.name.toLowerCase()})`);
      }
      lines.push('');
    }
    if (enums.length > 0) {
      lines.push('### Enums');
      for (const e of enums) {
        lines.push(`- [${e.name}](#${e.name.toLowerCase()})`);
      }
      lines.push('');
    }
    lines.push('---', '');
  }

  // Render Structs
  for (const s of structs) {
    lines.push(`## ${s.name}`, '');
    if (s.description) {
      lines.push(`${s.description}\n`);
    }

    lines.push('| Field | Type | Required | Description |');
    lines.push('| :--- | :--- | :--- | :--- |');

    for (const f of s.fields) {
      const typeStr = formatTypeForMarkdown(f.type);
      const reqStr = f.optional ? 'No' : '**Yes**';
      const descStr = f.description ? f.description.replace(/\|/g, '\\|') : '-';
      lines.push(`| \`${f.name}\` | ${typeStr} | ${reqStr} | ${descStr} |`);
    }
    lines.push('', '---', '');
  }

  // Render Enums
  for (const e of enums) {
    lines.push(`## ${e.name}`, '');
    if (e.description) {
      lines.push(`${e.description}\n`);
    }

    lines.push('| Variant | Value | Description |');
    lines.push('| :--- | :--- | :--- |');

    for (const v of e.values) {
      const descStr = v.description ? v.description.replace(/\|/g, '\\|') : '-';
      lines.push(`| \`${v.name}\` | \`"${v.value}"\` | ${descStr} |`);
    }
    lines.push('', '---', '');
  }

  return lines.join('\n');
}

function formatTypeForMarkdown(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      return `\`${node.primitive}\``;
    case 'reference':
      return `[\`${node.name}\`](#${node.name.toLowerCase()})`;
    case 'array':
      return `${formatTypeForMarkdown(node.elementType)}[]`;
    case 'map':
      return `Map<${formatTypeForMarkdown(node.keyType)}, ${formatTypeForMarkdown(node.valueType)}>`;
    case 'optional':
      return `${formatTypeForMarkdown(node.innerType)}?`;
    case 'union':
      return node.types.map(formatTypeForMarkdown).join(' \\| ');
    case 'literal':
      return `\`"${node.value}"\``;
    default:
      return '`any`';
  }
}
